SELECT cs.cs_sold_date_sk, cs.cs_quantity, CASE WHEN cs.cs_quantity > 75 THEN 'High' WHEN cs.cs_quantity > 79 THEN 'Medium' ELSE 'Low' END AS quantity_category, cs.cs_ext_sales_price * 1409.98 AS adjusted_sales_price, cs.cs_ext_sales_price - cs.cs_ext_discount_amt AS net_sales_before_tax, (cs.cs_ext_sales_price - cs.cs_ext_discount_amt) * 0.1 AS estimated_tax, cs.cs_ext_sales_price - cs.cs_ext_discount_amt + (cs.cs_ext_sales_price - cs.cs_ext_discount_amt) * 0.1 AS estimated_total, t.t_hour, t.t_am_pm, CONCAT(t.t_am_pm, ' ', t.t_shift) AS time_of_day, CASE WHEN t.t_hour BETWEEN 6 AND 11 THEN 'Morning' WHEN t.t_hour BETWEEN 12 AND 17 THEN 'Afternoon' WHEN t.t_hour BETWEEN 18 AND 21 THEN 'Evening' ELSE 'Night' END AS period_of_day FROM catalog_sales cs JOIN time_dim t ON cs.cs_sold_time_sk = t.t_time_sk WHERE cs.cs_sold_date_sk = 2450838 AND t.t_meal_time = 'breakfast           '
